"""Data catalogue (``configs/data/sources.yaml``) and the licence gate.

Every download, build and training mixture refers to sources by name, so the
licence decision is made once, here:

* ``blocked`` sources are refused - non-commercial (``--allow-noncommercial``
  overrides it; a bank should not), naming / derivative clauses
  (``--allow-naming-clause``), suspended (never);
* ``needs_counsel`` sources need ``--accept-counsel`` (sign-off recorded in the
  data card);
* ``eval_only`` sources are refused for any training use;
* text generated by models whose licence propagates (Llama, Gemma) is blocked
  even if the source itself is marked ``use``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

TIERS = ("use", "needs_counsel", "eval_only", "blocked")
KINDS = ("pretrain", "parallel", "sft", "preference", "safety", "eval")
_PROPAGATING = re.compile(r"\b(?:llama|gemma)\b", re.I)
_NONCOMMERCIAL = re.compile(r"\bNC\b|non-?commercial|research only", re.I)


@dataclass
class Source:
    name: str
    kind: str
    langs: list[str]
    tier: str
    license: str
    generated_by: str = "unknown"
    hf: dict | None = None
    url: str | None = None
    converter: str | None = None
    block_reason: str | None = None
    exclude_subsets: list[str] = field(default_factory=list)
    internal: bool = False
    verify: bool = False
    notes: str = ""

    def problems(self) -> list[str]:
        out = []
        if self.kind not in KINDS:
            out.append(f"{self.name}: unknown kind {self.kind!r}")
        if self.tier not in TIERS:
            out.append(f"{self.name}: unknown tier {self.tier!r}")
        if self.tier == "use" and _NONCOMMERCIAL.search(self.license):
            out.append(f"{self.name}: licence {self.license!r} looks non-commercial but tier is 'use'")
        if self.tier == "blocked" and not self.block_reason:
            out.append(f"{self.name}: blocked without block_reason")
        return out


@dataclass
class GateDecision:
    allowed: bool
    reason: str


def load_sources(path: str | Path = "configs/data/sources.yaml") -> dict[str, Source]:
    from dsm.utils import load_yaml

    entries = load_yaml(path)["sources"]
    sources = {}
    for entry in entries:
        source = Source(**entry)
        if source.name in sources:
            raise ValueError(f"duplicate source name {source.name!r}")
        sources[source.name] = source
    return sources


def check(
    source: Source,
    *,
    purpose: str = "train",
    accept_counsel: bool = False,
    allow_noncommercial: bool = False,
    allow_naming_clause: bool = False,
) -> GateDecision:
    """May ``source`` be used for ``purpose`` ("train" or "eval")?"""
    if source.tier == "blocked":
        reason = source.block_reason or "blocked"
        if reason == "noncommercial" and allow_noncommercial:
            return GateDecision(
                True,
                "non-commercial source allowed by --allow-noncommercial (never for a commercial release)",
            )
        if reason == "naming_clause" and allow_naming_clause:
            return GateDecision(
                True,
                "naming-clause source allowed by --allow-naming-clause (the released model name must comply)",
            )
        return GateDecision(False, f"blocked: {reason} ({source.license})")
    if purpose == "train" and _PROPAGATING.search(source.generated_by) and not allow_naming_clause:
        return GateDecision(
            False, f"generated by {source.generated_by}: that model licence propagates to trained models"
        )
    if source.tier == "eval_only" and purpose != "eval":
        return GateDecision(False, "evaluation benchmark: never train on it")
    if source.tier == "needs_counsel" and not accept_counsel:
        return GateDecision(
            False, f"needs counsel sign-off ({source.license}); pass --accept-counsel once approved"
        )
    return GateDecision(True, f"{source.tier}: {source.license}")


def gate(names: list[str], sources: dict[str, Source], **flags) -> list[Source]:
    """Sources for ``names``; raises with every refusal explained."""
    refused, ok = [], []
    for name in names:
        if name not in sources:
            refused.append(f"{name}: not in the catalogue")
            continue
        decision = check(sources[name], **flags)
        (ok if decision.allowed else refused).append(
            sources[name] if decision.allowed else f"{name}: {decision.reason}"
        )
    if refused:
        raise PermissionError("licence gate refused:\n  " + "\n  ".join(refused))
    return ok
